CREATE TABLE mistri.job_attempt (
    job_id text NOT NULL COLLATE pg_catalog."C",
    attempt integer NOT NULL,
    fence text COLLATE pg_catalog."C",
    started_at bigint NOT NULL,
    deadline bigint,
    outcome text NOT NULL COLLATE pg_catalog."C",
    code text COLLATE pg_catalog."C",
    finished_at bigint,
    operator text COLLATE pg_catalog."C",
    CONSTRAINT job_attempt_attempt_check CHECK (((attempt >= 1) AND (attempt <= 131))),
    CONSTRAINT job_attempt_check CHECK ((((outcome = 'redriven'::text) AND (fence IS NULL) AND (deadline IS NULL) AND (code IS NOT NULL) AND (code = 'redriven'::text) AND (finished_at IS NOT NULL) AND (finished_at = started_at) AND (operator IS NOT NULL)) OR ((outcome <> 'redriven'::text) AND (fence IS NOT NULL) AND (deadline IS NOT NULL) AND (deadline > started_at) AND (operator IS NULL) AND (((outcome = 'leased'::text) AND (code IS NULL) AND (finished_at IS NULL)) OR ((outcome <> 'leased'::text) AND (code IS NOT NULL) AND (code <> 'redriven'::text) AND (finished_at IS NOT NULL) AND (finished_at >= started_at)))))),
    CONSTRAINT job_attempt_code_check CHECK ((code = ANY (ARRAY['succeeded'::text, 'rejected'::text, 'not_authorized'::text, 'timeout'::text, 'shutdown'::text, 'lease_expired'::text, 'cancelled'::text, 'input_invalid'::text, 'handler_error'::text, 'redriven'::text]))),
    CONSTRAINT job_attempt_fence_check CHECK (((fence IS NULL) OR (octet_length(fence) = 36))),
    CONSTRAINT job_attempt_operator_check CHECK (((operator IS NULL) OR ((octet_length(operator) >= 1) AND (octet_length(operator) <= 128)))),
    CONSTRAINT job_attempt_outcome_check CHECK ((outcome = ANY (ARRAY['leased'::text, 'succeeded'::text, 'failed'::text, 'retry'::text, 'unknown'::text, 'cancelled'::text, 'redriven'::text]))),
    CONSTRAINT job_attempt_started_at_check CHECK ((started_at >= 0))
);
CREATE TABLE mistri.job_job (
    id text NOT NULL COLLATE pg_catalog."C",
    seq bigint NOT NULL,
    job text NOT NULL COLLATE pg_catalog."C",
    version bigint NOT NULL,
    idempotency_key text NOT NULL COLLATE pg_catalog."C",
    fingerprint text NOT NULL COLLATE pg_catalog."C",
    input_json text NOT NULL COLLATE pg_catalog."C",
    provenance_json text NOT NULL COLLATE pg_catalog."C",
    state text NOT NULL COLLATE pg_catalog."C",
    attempts integer NOT NULL,
    max_attempts integer NOT NULL,
    redrives integer NOT NULL,
    attempt_limit integer NOT NULL,
    run_at bigint NOT NULL,
    created_at bigint NOT NULL,
    updated_at bigint NOT NULL,
    fence text COLLATE pg_catalog."C",
    lease_until bigint,
    cancel_requested integer NOT NULL,
    last_code text COLLATE pg_catalog."C",
    result_json text COLLATE pg_catalog."C",
    namespace text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT job_job_attempt_limit_check CHECK (((attempt_limit >= 1) AND (attempt_limit <= 131))),
    CONSTRAINT job_job_attempts_check CHECK (((attempts >= 0) AND (attempts <= 131))),
    CONSTRAINT job_job_cancel_requested_check CHECK ((cancel_requested = ANY (ARRAY[0, 1]))),
    CONSTRAINT job_job_check CHECK ((attempts <= attempt_limit)),
    CONSTRAINT job_job_check1 CHECK ((((state = ANY (ARRAY['leased'::text, 'unknown'::text])) AND (fence IS NOT NULL) AND (octet_length(fence) = 36) AND (lease_until IS NOT NULL) AND (lease_until >= 0) AND (attempts > 0)) OR ((state <> ALL (ARRAY['leased'::text, 'unknown'::text])) AND (fence IS NULL) AND (lease_until IS NULL)))),
    CONSTRAINT job_job_check2 CHECK (((state <> 'scheduled'::text) OR ((attempts = 0) AND (last_code IS NULL)))),
    CONSTRAINT job_job_check3 CHECK (((result_json IS NULL) OR (state = 'succeeded'::text))),
    CONSTRAINT job_job_created_at_check CHECK ((created_at >= 0)),
    CONSTRAINT job_job_fingerprint_check CHECK ((fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT job_job_id_check CHECK ((octet_length(id) = 36)),
    CONSTRAINT job_job_idempotency_key_check CHECK (((octet_length(idempotency_key) >= 1) AND (octet_length(idempotency_key) <= 128))),
    CONSTRAINT job_job_input_json_check CHECK (((octet_length(input_json) >= 1) AND (octet_length(input_json) <= 65536))),
    CONSTRAINT job_job_job_check CHECK (((octet_length(job) >= 1) AND (octet_length(job) <= 128))),
    CONSTRAINT job_job_last_code_check CHECK ((last_code = ANY (ARRAY['succeeded'::text, 'rejected'::text, 'not_authorized'::text, 'timeout'::text, 'shutdown'::text, 'lease_expired'::text, 'cancelled'::text, 'input_invalid'::text, 'handler_error'::text, 'redriven'::text]))),
    CONSTRAINT job_job_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 32))),
    CONSTRAINT job_job_provenance_json_check CHECK (((octet_length(provenance_json) >= 1) AND (octet_length(provenance_json) <= 1024))),
    CONSTRAINT job_job_redrives_check CHECK (((redrives >= 0) AND (redrives <= 3))),
    CONSTRAINT job_job_result_json_check CHECK (((result_json IS NULL) OR ((octet_length(result_json) >= 1) AND (octet_length(result_json) <= 65536)))),
    CONSTRAINT job_job_run_at_check CHECK ((run_at >= 0)),
    CONSTRAINT job_job_seq_check CHECK ((seq >= 0)),
    CONSTRAINT job_job_state_check CHECK ((state = ANY (ARRAY['scheduled'::text, 'leased'::text, 'retry'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text, 'unknown'::text]))),
    CONSTRAINT job_job_updated_at_check CHECK ((updated_at >= 0)),
    CONSTRAINT job_job_version_check CHECK ((version >= 1))
);
CREATE TABLE mistri.job_policy (
    namespace text NOT NULL COLLATE pg_catalog."C",
